# Extract liked song IDs
liked_ids = {song['song_id'] for song in liked_songs}
print("Liked IDs:", liked_ids)

# Navigate to previous songs until we find a liked one
for step in range(10):
    result = apis.spotify.previous_song(access_token=access_token)
    print(f"Step {step+1}: {result}")
    song_id = result.get('song_id')
    if song_id in liked_ids:
        print(f"Found liked song with ID {song_id}")
        break
else:
    print("No liked song found in previous songs")

