steps.code:
# Search for each song in the archive to get its song_id
song_ids_to_archive = []
for song in songs_to_archive:
    title = song['title']
    artist = song['artist']
    # Search with query = title
    results = apis.spotify.search_songs(query=title, access_token=spotify_login['access_token'], page_limit=20)
    found = None
    if results:
        for song_result in results:
            # Check title match (case-insensitive)
            if song_result['title'].lower() == title.lower():
                # Check artist match (any artist in the list)
                artist_names = [a['name'] for a in song_result['artists']]
                if any(artist_name.lower() == artist.lower() for artist_name in artist_names):
                    found = song_result['song_id']
                    break
    if found is not None:
        song_ids_to_archive.append(found)
        print(f"Found: {title} by {artist} -> song_id {found}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print(f"\nTotal song IDs found: {len(song_ids_to_archive)}")

# Check which playlists contain the songs to archive
playlists_with_songs = {}
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    playlist_title = playlist['title']
    song_ids_in_playlist = playlist['song_ids']
    # Find which of our target song_ids are in this playlist
    common = set(song_ids_to_archive) & set(song_ids_in_playlist)
    if common:
        playlists_with_songs[playlist_id] = {
            'title': playlist_title,
            'song_ids': list(common)
        }
        print(f"Playlist '{playlist_title}' (id={playlist_id}) contains {len(common)} songs to archive: {common}")

print(f"\nTotal playlists with songs to remove: {len(playlists_with_songs)}")

