# Fetch details for each unique song ID to match against archive
song_details = {}
for sid in song_ids_to_check:
    try:
        song = apis.spotify.show_song(song_id=sid, access_token=login_result["access_token"])
        song_details[sid] = song
    except Exception as e:
        print(f"Error fetching song {sid}: {e}")

# Print a sample to verify structure
print("Sample song details:", list(song_details.items())[:2])

