steps.code:
# Verify that all archived songs have been removed from all playlists except 654
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
print("Archived song IDs:", sorted(archived_song_ids))

# Check each playlist (except 654) for any remaining archived songs
for playlist in all_playlists:
    if playlist["playlist_id"] == 654:
        continue
    remaining = [sid for sid in playlist["song_ids"] if sid in archived_song_ids]
    if remaining:
        print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) still has archived songs: {remaining}")
        # Remove them
        for sid in remaining:
            result = apis.spotify.remove_song_from_playlist(playlist_id=playlist["playlist_id"], song_id=sid, access_token=login_result["access_token"])
            print(f"Removed song_id {sid} from playlist {playlist['playlist_id']}: {result}")
    else:
        print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) is clean.")

# Also verify that all archived songs are in the 'Old Songs' playlist (654)
old_songs_playlist = next(p for p in all_playlists if p["playlist_id"] == 654)
missing_from_old = archived_song_ids - set(old_songs_playlist["song_ids"])
if missing_from_old:
    print(f"Missing from Old Songs: {missing_from_old}")
else:
    print("All archived songs are in Old Songs playlist.")

