steps.code:
# Let's write a function to find the song_id for each song in the list, searching and matching title and artists.
# We'll store results in a dict mapping title to song_id.

song_ids = {}
for song in songs_to_archive:
    title = song['title']
    artists_expected = set(song['artists'])
    # Search with title
    result = apis.spotify.search_songs(query=title, access_token=spotify_login['access_token'], page_limit=20)
    found = None
    if isinstance(result, list):
        for item in result:
            if item['title'].lower() == title.lower():
                result_artists = {artist['name'] for artist in item['artists']}
                if artists_expected == result_artists:
                    found = item['song_id']
                    break
    song_ids[title] = found
    print(f"{title}: {found}")

print("All song IDs:", song_ids)

