# Let's search for all songs in the list to get their song_ids.
# We'll build a mapping from (title, tuple_of_artists) to song_id.
song_id_map = {}
for song in songs_to_archive:
    title = song["title"]
    artists = song["artists"]
    # Build query: title + first artist (or all artists joined)
    query = title + " " + " ".join(artists)
    results = apis.spotify.search_songs(query=query, access_token=spotify_token)
    # Find exact match: title matches and all artists are present
    best_match = None
    for r in results:
        if r["title"].lower() == title.lower():
            result_artists = {a["name"].lower() for a in r["artists"]}
            expected_artists = {a.lower() for a in artists}
            if expected_artists.issubset(result_artists):
                best_match = r
                break
    if best_match:
        song_id_map[(title, tuple(artists))] = best_match["song_id"]
        print(f"Found: {title} by {', '.join(artists)} -> song_id {best_match['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {', '.join(artists)}")

print(f"\nTotal mapped: {len(song_id_map)}")

# Create set of archived song_ids
archived_song_ids = set(song_id_map.values())
print("Archived song IDs:", archived_song_ids)

# Remove these songs from all playlists
for playlist in playlists:
    pid = playlist["playlist_id"]
    for song_id in playlist["song_ids"]:
        if song_id in archived_song_ids:
            result = apis.spotify.remove_song_from_playlist(playlist_id=pid, song_id=song_id, access_token=spotify_token)
            print(f"Removed song {song_id} from playlist {pid}: {result}")

