# Parse the old songs list and search for each song to get its song_id
import re

# Parse file content
content = file_data['content']
old_songs = []
for line in content.splitlines():
    line = line.strip()
    if line.startswith('- '):
        # Remove leading "- " and split on " by "
        song_str = line[2:]
        if ' by ' in song_str:
            title, artists_str = song_str.split(' by ', 1)
            artists = [a.strip() for a in artists_str.split(',')]
            old_songs.append({'title': title.strip(), 'artists': artists})

print("Parsed old songs:")
for s in old_songs:
    print(s)

# Now search for each song and find the matching song_id
song_id_map = {}
for song in old_songs:
    title = song['title']
    artists = song['artists']
    # Build query: title + first artist (or all artists)
    query = title + ' ' + ' '.join(artists)
    results = apis.spotify.search_songs(query=query, access_token=spotify_token)
    # Find exact match
    found = None
    for r in results:
        if r['title'].lower() == title.lower():
            # Check artists match
            result_artists = {a['name'].lower() for a in r['artists']}
            expected_artists = {a.lower() for a in artists}
            if result_artists == expected_artists:
                found = r['song_id']
                break
    if found is None:
        # Try without artist filter, just title
        results2 = apis.spotify.search_songs(query=title, access_token=spotify_token)
        for r in results2:
            if r['title'].lower() == title.lower():
                # Check if any artist matches at least one expected artist
                result_artists = {a['name'].lower() for a in r['artists']}
                if any(a.lower() in result_artists for a in artists):
                    found = r['song_id']
                    break
    if found is None:
        print(f"WARNING: Could not find song: {title} by {artists}")
    else:
        song_id_map[title] = found
        print(f"Found: {title} -> song_id {found}")

print("\nSong ID map:")
print(song_id_map)

