# Let's search for each archived song to get its song_id
# We'll use query=title and paginate through results to find exact match

archived_song_ids = []
for song in songs_to_archive:
    title = song['title']
    artists = song['artists']
    found = None
    page_index = 0
    while True:
        results = apis.spotify.search_songs(query=title, access_token=spotify_token, page_index=page_index, page_limit=20)
        if not results:
            break
        for result in results:
            result_artists = [artist['name'] for artist in result['artists']]
            if set(artists) == set(result_artists):
                found = result
                break
        if found:
            break
        # If we got fewer than 20 results, we've exhausted pages
        if len(results) < 20:
            break
        page_index += 1
    if found:
        archived_song_ids.append(found['song_id'])
        print(f"Found: {title} -> song_id {found['song_id']}")
    else:
        print(f"NOT FOUND: {title}")

print("Archived song IDs:", archived_song_ids)

