steps.code:
# Parse the note content to extract songs and their release status
import re

content = note['content']
lines = content.strip().split('\n')
# Skip the first line (heading)
songs = []
for line in lines[1:]:
    line = line.strip()
    if not line.startswith('- '):
        continue
    # Remove leading "- "
    line = line[2:]
    # Split by " BY " to get title and artist part
    if ' BY ' in line:
        title_part, artist_part = line.split(' BY ', 1)
        # artist_part may contain " RELEASED_AT ..."
        if ' RELEASED_AT ' in artist_part:
            artist, released = artist_part.split(' RELEASED_AT ', 1)
        else:
            artist = artist_part
            released = None
        songs.append({
            'title': title_part.strip(),
            'artists': artist.strip(),
            'released': released.strip() if released else None
        })
    else:
        # malformed line, skip
        pass

