new_lines = []
for line in content.split('\n'):
    if line.startswith('- ') and 'RELEASED_AT TODO' in line:
        # Extract title to find release
        m = re.match(r'- (.+?) BY .+? RELEASED_AT TODO', line)
        if m:
            title = m.group(1).strip()
            if title in release_map:
                new_line = line.replace('RELEASED_AT TODO', f"RELEASED_AT {release_map[title]}")
                new_lines.append(new_line)
                print(f"Updated: {title} -> {release_map[title]}")
            else:
                print(f"Missing release for {title}")
                new_lines.append(line)
        else:
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print("\nNew content:")
print(new_content)

# Parse the note content to identify songs needing release month
content = note['content']
lines = content.strip().split('\n')
songs_to_update = []
for line in lines:
    if line.startswith('- '):
        # Extract song info
        # Format: - Song Title BY Artist1, Artist2 RELEASED_AT TODO
        # Remove leading "- "
        line = line[2:]
        # Split on " RELEASED_AT "
        if ' RELEASED_AT ' in line:
            song_part, release_part = line.split(' RELEASED_AT ', 1)
            if release_part == 'TODO':
                # Extract title and artists
                # Format: Song Title BY Artist1, Artist2
                if ' BY ' in song_part:
                    title, artists_str = song_part.split(' BY ', 1)
                    artists = [a.strip() for a in artists_str.split(',')]
                    songs_to_update.append({'title': title.strip(), 'artists': artists, 'line': line})
                else:
                    print(f"Unexpected format: {line}")
            else:
                # Already has release info
                pass
        else:
            print(f"No RELEASED_AT in line: {line}")

print(f"Found {len(songs_to_update)} songs to update")
for s in songs_to_update:
    print(s)

