# Search for all songs and collect release dates
release_info = {}
for song in songs_to_update:
    result = apis.spotify.search_songs(query=song['title'], access_token=spotify_token, page_limit=20)
    matches = []
    for s in result:
        if s['title'].lower() == song['title'].lower():
            song_artist_names = [a['name'].lower() for a in s['artists']]
            note_artists_lower = [a.lower() for a in song['artists']]
            if all(artist in song_artist_names for artist in note_artists_lower):
                matches.append(s)
    if len(matches) == 1:
        release_date = matches[0]['release_date']  # e.g., "2021-03-23T13:53:26"
        # Extract month/year
        year = release_date[:4]
        month = release_date[5:7]
        release_info[song['title']] = f"{month}/{year}"
        print(f"{song['title']} -> {month}/{year}")
    else:
        print(f"WARNING: {len(matches)} matches for {song['title']}")
        for m in matches:
            print(m)

