# Compute positions of liked songs in the queue
liked_ids = {song['song_id'] for song in liked_songs}
queue_positions = {song['position']: song['song_id'] for song in queue}
positions_to_remove = [pos for pos, sid in queue_positions.items() if sid in liked_ids]
positions_to_remove.sort(reverse=True)
print("Positions to remove (descending):", positions_to_remove)

